       a.manager,
       t.ticket_id,
       t.priority AS ticket_priority,
       t.status AS ticket_status,
       t.sla_status,
       t.sla_target_date,
       t.resolved_date,
       t.resolution_notes,
       t.change_request_id,
       DATEDIFF(day, f.created_date, ISNULL(f.closed_date, GETDATE())) AS days_open,
